<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta http-equiv="refresh" content="30"><meta name="theme-color" content="#061b3a"><title>Live Scoreboard · TallyTech</title><link rel="stylesheet" href="<?= base_url('assets/css/app.css') ?>"></head><body class="viewer-page"><header class="viewer-nav"><a class="viewer-brand" href="<?= site_url('scoreboard') ?>"><img src="<?= base_url('assets/img/logo.png') ?>" alt="TallyTech"><b>TallyTech</b></a><div><span>LIVE</span><a href="<?= site_url('login') ?>" class="btn viewer-login">Login</a></div></header><section class="score-hero"><div class="live-pill">● LIVE · <?= esc($activeEvent['name']??'ISF') ?></div><h1>Live Scoreboard</h1><p>Scores, rankings, and results — refreshed automatically every 30 seconds.</p><small>Official standings use validated results only. Unofficial submissions remain visible and clearly marked.</small></section><main class="viewer-content">
<section><div class="section-title"><h2>🏆 Team Standings</h2><span>Official ranking</span></div><div class="viewer-podium"><?php foreach(array_slice($ranking??[],0,4) as $i=>$t): ?><article class="viewer-rank r<?= $i+1 ?>"><span><?= ['🏆','🥈','🥉','🎯'][$i] ?></span><b><?= $i+1 ?></b><h3><?= esc($t['name']) ?></h3><strong><?= number_format((float)$t['total_points'],0) ?></strong><small>points</small></article><?php endforeach; ?></div></section>
<section class="viewer-panel"><div class="section-title"><h2>Overall Team Ranking</h2><span>Validated results only</span></div><div class="table-wrap"><table><thead><tr><th>Rank</th><th>Team</th><th>Points</th><th>1st</th><th>2nd</th><th>3rd</th></tr></thead><tbody><?php foreach($ranking as $i=>$t): ?><tr><td><b><?= $i+1 ?></b></td><td><?= esc($t['name']) ?></td><td><b><?= number_format((float)$t['total_points'],0) ?></b></td><td><?= $t['firsts'] ?></td><td><?= $t['seconds'] ?></td><td><?= $t['thirds'] ?></td></tr><?php endforeach; ?></tbody></table></div></section>
